        readonly description: "按 farmId 读取区域身份、资源哈希、运行状态和错误；不返回可写的服务或资源对象。 输入 farmId 必须来自 list，未知区域 NOT_FOUND；只读完成后可用 capabilities 验证依赖。";
        readonly input: z.ZodObject<{
            farmId: z.ZodString;
        }, z.core.$strict>;
    };
    readonly capabilities: {
        readonly effect: "read";
        readonly description: "查询当前可执行的操作与依赖；无 farmId 时读取系统通用能力，scope.kind=system；这时 interactionHostBound/targetQueryAvailable/presentation=null 表示未选择农场，不能推断任何农场不可用；用 list 得到 farmId 后再查区域能力。指定 farmId 才查询区域交互宿主，targetQueryAvailable 指示 getTarget 是否可用。presentation 是 interactionHostBound 的兼容别名，不等于诊断中的表现资源就绪。 只读，指定未知区域 NOT_FOUND；operations 是当时的能力事实，执行前仍须校验，不能解锁未初始化或禁用区域。";
        readonly input: z.ZodObject<{
            farmId: z.ZodOptional<z.ZodString>;
        }, z.core.$strict>;
    };
    readonly getCatalog: {
        readonly effect: "read";
        readonly description: "读取真实可用种子、作物、生长周期、growthFactors 生长因素阈值、产物及storage容器类型/逐作物容量（仓储篮子为硬容量，马车为显示容量，上限60份）；播种使用 seedId，收获使用 cropInstanceId。growthFactors 的 minimum/maximum 是生长边界，optimalMinimum/optimalMaximum 是适宜范围，单位与 getPlot.crop.factors 一致；根据实际读回决定是否浇水，不修改目录。farmId 必须已配置资源；资源不一致 INVALID_DEFINITION。只读结果中的 seed.cropId 应能在 crops 中找到。growthTarget 是成长量，baseGrowthUnitsPerSecond 是每秒速率，理想成熟毫秒数为两者之比乘 1000；产物数量为整数。";
        readonly input: z.ZodObject<{
            farmId: z.ZodString;
        }, z.core.$strict>;
    };
    readonly getTarget: {
        readonly effect: "read";
        readonly description: "读取宿主当前选中地块或待开垦网格；无交互宿主返回 NOT_SUPPORTED，不猜测目标。 前提是区域已初始化；无副作用。对结果用 getPlot 或 inspectCultivation 重新检查，不能把一次选中当成永久授权。";
        readonly input: z.ZodObject<{
            farmId: z.ZodString;
        }, z.core.$strict>;
    };
    readonly queryPlots: {
        readonly effect: "read";
        readonly description: "按地形、水平米制范围、整备、可用性、占用和 cropId 过滤；成熟判断读 crop.mature，停止生长原因读 pausedReason 和 factors。 输入 farmId/query，cell 为整数，bounds 单位米；只读返回过滤后的地块数组，空结果为 []。可用 getPlot 核验其中实例。";
        readonly input: z.ZodObject<{
            query: z.ZodOptional<z.ZodObject<{
                groundId: z.ZodOptional<z.ZodString>;
                bounds: z.ZodOptional<z.ZodObject<{
