                    minimumZ: z.ZodNumber;
                    maximumZ: z.ZodNumber;
                }, z.core.$strict>>;
                preparation: z.ZodOptional<z.ZodEnum<{
                    leveled: "leveled";
                }>>;
                availability: z.ZodOptional<z.ZodEnum<{
                    available: "available";
                    blocked: "blocked";
