    readonly getEnvironment: {
        readonly effect: "read";
        readonly description: "只读返回当前宿主环境（季节、基准温度、雪、气温、光照、雨强）、农业时间及最近结算气温光照；nearWater为宿主缓存刷新诊断（版本、调用数、切片耗时和超预算次数），未接入为null。静态基线明确标记。不推进时间或采样Water。";
        readonly input: z.ZodObject<{
            farmId: z.ZodString;
        }, z.core.$strict>;
    };
    readonly damageCrop: {
        readonly effect: "command";
        readonly description: "对指定 plotId/cropInstanceId 提交正整数 damagePermille 和 source（animal/pest/storm/wind/other），允许超过1000，实际伤害截断到剩余健康；不接受 pestPressureDeltaUnits。独立于农具和动物系统。返回 receipt（commandId/revision/ok/replayed）及健康前后、实际伤害、派生 healthStatus。健康降至0时在同一事务中自动移除作物并释放耕地，恢复已锄状态，不产生收获物；无论是否成熟都立即清理。原伤害请求可幂等重放；清理后新的伤害请求返回 CROP_NOT_FOUND，已重新种植则返回 CROP_INSTANCE_CHANGED；仍校验实例和版本。CROP_NOT_FOUND/CROP_INSTANCE_CHANGED/INVALID_ARGUMENT/版本冲突明确失败。重试须保留完整 request 和捕获版本；同ID改参拒绝，STORAGE_FAILURE 的 retryRequest 可原样重试。";
        readonly input: z.ZodObject<{
            cropInstanceId: z.ZodString;
            damagePermille: z.ZodNumber;
            source: z.ZodEnum<{
                wind: "wind";
                storm: "storm";
                other: "other";
                pest: "pest";
                animal: "animal";
            }>;
            plotId: z.ZodString;
            farmId: z.ZodString;
        }, z.core.$strict>;
        readonly options: z.ZodObject<{
            commandId: z.ZodOptional<z.ZodString>;
            expectedRevision: z.ZodOptional<z.ZodNumber>;
            expectedCarriedItemId: z.ZodOptional<z.ZodString>;
            expectedGroundRevision: z.ZodOptional<z.ZodNumber>;
        }, z.core.$strict>;
    };
    readonly getPlot: {
        readonly effect: "read";
        readonly description: "返回地块及当前作物实例、成熟度、诊断和版本；不存在返回 null，未加载地形的位置为 null。 输入 farmId/plotId；只读，水分为体积含水率百分点，成长与健康度为千分比，剩余时间为毫秒。waterRates并列返回当前雨水、河湖补水和蒸发速率；nearWater含缓存来源hash、岸距/高差（米）、0..1系数、版本和refreshing标记，刷新中沿用旧完整缓存。查询不采样Water。操作后重查当前实例。";
